from pathlib import Path
p=Path('index.html')
s=p.read_text(encoding='utf-8')
anchor='''  const regionIntent16537=/^(?:state|province|region)\\s+of\\b|\\b(?:state|province|region)\\s*$/.test(raw16537);\n  const countryIntent16537=/\\b(?:country|nation)\\s*$/.test(raw16537);\n'''
insert='''  /* EARTHLINE 16846 — bare country identity. A short, unqualified place name may\n     collide with a city/locality while the sovereign country is returned under a\n     close English exonym (for example one spelling differs by a single letter).\n     Prefer a country only when its normalized name is an exact or very close match;\n     addresses, comma-qualified searches and explicit city/region intent keep the\n     existing scorer. This is global identity routing only; hydrology is unchanged. */\n  const bareCountryQuery16846=!/[0-9,@]/.test(String(query16537||''))&&raw16537.split(/\\s+/).filter(Boolean).length<=4;\n  if(bareCountryQuery16846){\n    const editDistance16846=(a16846,b16846)=>{\n      const a=String(a16846||''),b=String(b16846||'');\n      if(a===b)return 0;if(!a.length)return b.length;if(!b.length)return a.length;\n      let prev=Array.from({length:b.length+1},(_,i)=>i),cur=new Array(b.length+1);\n      for(let i=1;i<=a.length;i++){cur[0]=i;for(let j=1;j<=b.length;j++)cur[j]=Math.min(cur[j-1]+1,prev[j]+1,prev[j-1]+(a[i-1]===b[j-1]?0:1));const t=prev;prev=cur;cur=t;}\n      return prev[b.length];\n    };\n    let countryBest16846=null,countryScore16846=-Infinity;\n    for(let i16846=0;i16846<rows16537.length;i16846++){\n      const c16846=rows16537[i16846];if(earthlinePlaceType16537(c16846)!=='country')continue;\n      const names16846=[c16846.text,(c16846.place_name||'').split(',')[0]].map(earthlinePlaceKey16537).filter(Boolean);\n      for(const name16846 of names16846){\n        const maxLen16846=Math.max(raw16537.length,name16846.length,1),dist16846=editDistance16846(raw16537,name16846),similarity16846=1-dist16846/maxLen16846;\n        const queryTokens16846=raw16537.split(/\\s+/).filter(t=>t.length>=4),nameTokens16846=new Set(name16846.split(/\\s+/));\n        const shared16846=queryTokens16846.filter(t=>nameTokens16846.has(t)).length;\n        const close16846=raw16537===name16846||(similarity16846>=0.84&&(shared16846>0||raw16537.indexOf(' ')<0));\n        if(!close16846)continue;\n        const score16846=similarity16846*100+Math.max(0,Math.min(1,Number(c16846.relevance)||0))*10-i16846*.01;\n        if(score16846>countryScore16846){countryScore16846=score16846;countryBest16846=c16846;}\n      }\n    }\n    if(countryBest16846)return countryBest16846;\n  }\n'''
if anchor not in s:
    raise SystemExit('16846 selector anchor not found')
if 'bareCountryQuery16846' in s:
    raise SystemExit('16846 selector patch already present')
s=s.replace(anchor,insert+anchor,1)
p.write_text(s,encoding='utf-8')
print('patched selector: EARTHLINE 16846 generic bare-country identity preference')
